package mcpserver

var descriptions = map[string]string{
	"health":               "Check that Krita is running with the MCP plugin enabled.",
	"new_canvas":           "Create an RGBA/U8 canvas; width and height are positive pixel dimensions.",
	"set_color":            "Set foreground color using #RGB, #RRGGBB or Qt #AARRGGBB hex (alpha first).",
	"set_brush":            "Set the actual native brush preset (partial name match), integer pixel size and opacity 0..1. Preset controls hardness and pressure response; there is no hardness argument.",
	"stroke":               "Paint using the actual current preset. Canvas points are [x,y] or [x,y,pressure], 2..4096 points. Scalar pressure multiplies point pressure (0..1). Null curve uses Catmull-Rom when smooth, otherwise linear; explicit linear/bezier overrides smooth. Cubic Bezier requires 3n+1 points. Tapers are fractions of path length. Unit pressures without taper use one paintPath; otherwise sampled paintLine calls reset smudge state, round coordinates and can build alpha or create multiple undo steps. undo_steps is expected, not verified; inspect engine, mode, native_calls, undo_steps_verified and fidelity_warning. Temporary color/size/opacity/alpha lock are restored. Returns plugin details intact; no raster fallback.",
	"fill":                 "Paint a filled circle at canvas pixel (x,y), not a flood fill.",
	"draw_shape":           "Draw a native rectangle, ellipse or line in canvas pixels. (x,y) is top-left or line start; x2/y2 override the width/height endpoint. Fill paints the interior and stroke the outline.",
	"get_canvas":           "Export a PNG preview, allowing 120 seconds; return path, width, height and optional separate diff_path. Grid and reference difference affect exported copies only, never document pixels. diff_with_reference is a local image path.",
	"undo":                 "Request native undo; an enabled action does not verify a history change.",
	"redo":                 "Request native redo; an enabled action does not verify a history change.",
	"clear":                "Native active-layer fill respecting selection, opacity and alpha lock, not raw replacement.",
	"save":                 "Save/export the active document to an explicit local path, allowing 120 seconds.",
	"get_color_at":         "Sample the document projection at integer canvas pixel (x,y).",
	"list_brushes":         "List native brush presets by partial name, with a positive result limit.",
	"open_file":            "Open an existing local .kra, .png, .jpg or other Krita-supported file.",
	"fill_polygon":         "Fill a closed polygon of 3..4096 canvas [x,y] vertices, optionally Catmull-Rom smoothed. Null color uses foreground. Zero feather paints the active layer; feather 0..256 pixels creates an independent layer and returns layer_id. preserve_alpha=True is invalid for feathered fills. Generated pixels clip to selection, never automatically merge.",
	"gradient_polygon":     "Generate a gradient polygon on an independent new RGBA/U8 layer; return layer_id and target_layer_id. Canvas [x,y] vertices optionally use closed Catmull-Rom smoothing and feather. Linear direction is degrees (0 left-to-right, 90 top-to-bottom); radial goes from center color to gradient_end_color at polygon bounds. Selection clips pixels, target identity/pixels remain unchanged and active target is restored. No automatic merge; preserve_alpha=True is rejected before mutation.",
	"create_layer":         "Create and activate a paint layer using normal/multiply/screen/add/overlay; return layer_id.",
	"set_layer_properties": "Change the named layer or active layer when layer_id is null. Null properties remain unchanged. Opacity is 0..1; preserve_alpha sets persistent native alpha lock.",
	"list_layers":          "List document layers, stable IDs, properties and active-layer state.",
	"set_active_layer":     "Activate a layer by an ID returned from list_layers or create_layer.",
	"select_rect":          "Replace selection with a rectangle at integer canvas pixel (x,y), with positive integer dimensions.",
	"select_ellipse":       "Replace selection with an ellipse inside the integer canvas rectangle (x,y,width,height).",
	"select_polygon":       "Replace selection with a closed [x,y] polygon; smooth=True uses Catmull-Rom curves.",
	"select_by_alpha":      "Select active-layer pixels by byte alpha threshold 1..255 (default 1, not normalized).",
	"deselect":             "Remove the document selection via native setSelection(None).",
	"fill_selection":       "Natively fill the active selection on the active layer; null color uses foreground. preserve_alpha requests native alpha lock, not an independent generated layer.",
	"get_current_brush":    "Return actual currentBrushPreset and native brush settings, not a simulated renderer.",
	"batch":                "Prevalidate all {action,params} commands then submit ONE unrestricted, sequential, non-atomic batch. Actions omit krita_; nested batches are forbidden. No total command cap, aggregate budget, chunking, atomic flag, rollback or automatic retry. Runtime failure retains prior changes and completed_count/results/failing_index. Only the plugin schedules incremental execution; the client waits without a read timeout. Transport failures may have unknown outcomes: inspect Krita before retrying. Multiple commands/pressure segments may create multiple undo steps.",
}
